and file_name like concat('%', #{keyword}, '%')
order by file_name asc, file_id desc order by file_size desc, file_id desc order by create_time desc, file_id desc

select  from ai_user_file
where del_flag = '0' and user_id = #{userId} and content_hash = #{contentHash}
order by file_id asc limit 1

